contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function with inputs: receiver and amount
    function run(address receiver, uint amount) public payable {
        // require that the call could possibly succeed from this caller (InvMutTest is the owner):
        // since InvMutTest deployed c in the checker setup, it should be the owner; no precondition here.
        // record balances before the call
        uint balC_before = address(c).balance;
        uint balReceiver_before = receiver.balance;
        bool reverted;

        // perform the call and capture whether it reverts
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // If the call did not revert then C's balance decreased by amount and receiver's balance increased by amount.
        // If it reverted then no change is required by this property.
        assert(reverted || (address(c).balance + amount == balC_before && receiver.balance == balReceiver_before + amount));
    }

    receive() external payable { }
}

